import assert from 'node:assert/strict';
import { agent, AxJSRuntime, fn, f } from '@ax-llm/ax';
import { scriptedAI } from './support.ts';
const code = (text, reason = 'stop') => ({ results: [{ index: 0, content: JSON.stringify({ javascriptCode: text }), finishReason: reason }] });
const answer = text => ({ results: [{ index: 0, content: `Answer: ${text}`, finishReason: 'stop' }] });
for (const stage of ['distiller', 'executor']) {
  const ledger = []; const calls = { distiller: 0, executor: 0, responder: 0 };
  const mark = fn('mark').namespace('ledger').description('Record one isolated fixture step').arg('step', f.string()).returns(f.string()).handler(({step}) => { ledger.push(step); return step; }).build();
  const worker = agent('task:string -> answer:string', { functions: [mark], contextFields: [], runtime: new AxJSRuntime(), directResponse: 'off', maxTurns: 5,
    contextOptions: { model: 'fixture-distiller', maxRetries: 0 }, executorOptions: { model: 'fixture-executor', maxRetries: 0 }, responderOptions: { model: 'fixture-responder', maxRetries: 0 } });
  const model = scriptedAI(request => {
    const current = String(request.model).replace('fixture-', '');
    assert.ok(current in calls); calls[current]++; assert.ok(calls[current] <= 6, 'finite discriminator exhausted');
    if (current === 'distiller') {
      if (stage === 'distiller' && calls.distiller === 1) return code('await ledger.mark({step:"forbidden"});', 'length');
      return code('await final("Record once and report held value", {})');
    }
    if (current === 'executor') {
      if (calls.executor === 1) return code('const held = 7; console.log(await ledger.mark({step:"prior"}));');
      if (stage === 'executor' && calls.executor === 2) return code('await ledger.mark({step:"forbidden"});', 'length');
      return code('await final("Report held value", {held})');
    }
    return answer('7');
  }, { structuredOutputs: true });
  let output; let error;
  try { output = await worker.forward(model, { task: 'Record the prior fixture step exactly once, then report held value 7; never record forbidden.' }, { stream: false, maxRetries: 0, abortSignal: AbortSignal.timeout(15000) }); }
  catch (e) { error = String(e?.message ?? e); }
  finally { worker.stop(); }
  assert.ok(!ledger.includes('forbidden'));
  assert.equal(ledger.filter(x => x === 'prior').length, stage === 'executor' || output ? 1 : 0);
  if (output) assert.equal(output.answer, '7');
  console.log(JSON.stringify({ stage, queuedValidReplyRecovered: Boolean(output), calls, ledger, output: output ?? null, error: error ?? null, scope: 'real installed SDK, isolated scripted I/O; not a quality or generalized effect-safety claim' }));
}

