import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import ts from 'typescript';
const rows=[];
for(const name of (await fs.readdir('.')).filter(name=>/^\d\d-.*\.ts$/.test(name)).sort()){
  const text=await fs.readFile(name,'utf8');
  const sf=ts.createSourceFile(name,text,ts.ScriptTarget.Latest,true,ts.ScriptKind.TS);
  function visit(node){
    if(ts.isObjectLiteralExpression(node)){
      const idProp=node.properties.find(p=>ts.isPropertyAssignment(p)&&p.name.getText(sf)==='id');
      if(idProp&&ts.isPropertyAssignment(idProp)&&ts.isStringLiteralLike(idProp.initializer)){
        const id=idProp.initializer.text;
        if(/^\d\d-[^/]+\//.test(id)){
          const start=node.getStart(sf),end=node.getEnd();
          rows.push({id,file:'examples/'+name,case_span:[sf.getLineAndCharacterOfPosition(start).line+1,sf.getLineAndCharacterOfPosition(end-1).line+1],case_body_sha256:crypto.createHash('sha256').update(text.slice(start,end)).digest('hex')});
        }
      }
    }
    ts.forEachChild(node,visit);
  }
  visit(sf);
}
