{
  id: '04-providers/deployment-reasoning-dialects', title: 'The deployment profile, not a DeepSeek-looking ID, owns reasoning syntax',
  features: ['deployment-profiles', 'reasoning-defaults', 'tool-choice-constraints', 'custom-endpoint'], modes: ['offline'],
  async run(ctx) {
    const policyTool: NonNullable<AxChatRequest['functions']>[number] = {
      name: 'lookupPolicy',
      description: 'Read the refund policy for a product category',
      parameters: {
        type: 'object',
        properties: { productCategory: { type: 'string', description: 'Product category to look up' } },
        required: ['productCategory'],
      },
    };
    const sent = new Map<string, Wire>();
    let fetchCalls = 0;
    for (const name of ['deepseek', 'together', 'openai-compatible'] as const) {
      // Omit the native model to exercise the released default, not the newer source-only name.
      const config = name === 'deepseek' ? {} : { model: 'deepseek-ai/DeepSeek-V4-Flash' };
      const service = ai({ name, apiKey: 'fixture-only', apiURL: 'https://fixture.invalid/v1', config, options: { fetch: async (_url, init) => { fetchCalls++; sent.set(name, body(init)); return chatResponse('4'); } } });
      const response = completed(await service.chat({ chatPrompt: prompt, functions: [policyTool], functionCall: 'auto' }, { stream: false, abortSignal: ctx.signal }));
      assert.equal(response.results[0]?.content, '4');
      if (name === 'deepseek') {
        assert.equal(sent.get(name)?.model, AxAIDeepSeekModel.DeepSeekV4Flash);
        assert.deepEqual(sent.get(name)?.tools, [{ type: 'function', function: policyTool }]);
        assert.equal(sent.get(name)?.tool_choice, undefined);
        const calls = fetchCalls;
        for (const functionCall of ['required', { type: 'function', function: { name: policyTool.name } }, { type: 'function', function: { name: '__axOutput' } }] as const) {
          await assert.rejects(() => service.chat({ chatPrompt: prompt, functions: [policyTool], functionCall }, { stream: false, abortSignal: ctx.signal }), /tool.choice|forced|function.call/i);
          assert.equal(fetchCalls, calls);
        }
      }
    }
    assert.equal(fetchCalls, 3);
    assert.deepEqual(sent.get('deepseek')?.thinking, { type: 'enabled' });
    assert.equal(sent.get('deepseek')?.reasoning_effort, 'max');
    assert.equal(sent.get('openai-compatible')?.thinking, undefined);
    assert.equal(sent.get('openai-compatible')?.reasoning_effort, undefined);
    assert.equal(sent.get('together')?.thinking, undefined);
    assert.equal(sent.get('together')?.reasoning_effort, 'max');
    return { native: { model: sent.get('deepseek')?.model, thinking: sent.get('deepseek')?.thinking, effort: sent.get('deepseek')?.reasoning_effort }, fetchCalls, together: sent.get('together'), customDoesNotInferReasoning: true, scope: 'released wire contracts only; official DeepSeekFlash/default/image additions unavailable in supplied package, no live quality or alias verification' };
  },
},

{
  id: '32-executor-context/prompt-detail-comparison',
  title: 'Reuse invoice state under both declared prompt detail settings',
  features: ['promptLevel', 'liveRuntimeState', 'explicit stage routing', 'distiller handoff'],
  modes: ['offline'],
  async run(ctx) {
    const results: { level: string; systemChars: number; total: number }[] = [];
    for (const level of ['default', 'detailed'] as const) {
      let executorSystem = '', calls = 0;
      const worker = agent('task:string -> answer:string', {
        runtime: new AxJSRuntime(), promptLevel: level, maxTurns: 4, directResponse: 'off',
        contextOptions: { model: 'fixture-distiller' },
        executorOptions: { model: 'fixture-executor' },
        responderOptions: { model: 'fixture-responder' },
        contextPolicy: { preset: 'adaptive', budget: 'balanced' },
      });
      const responses = [
        code('await final("Compute the invoice sum from these amounts", { amounts: [9, 4] })'),
        code('const amounts = inputs.distilledContext.amounts; console.log(amounts.length)'),
        code('const sum = amounts.reduce((a, b) => a + b, 0); console.log(sum)'),
        code('await final("Report the observed invoice total", { sum })'), answer('13'),
      ];
      // The distiller request is not the executor prompt. Explicit model routes
      // identify the stage without injecting or modifying its SDK instructions.
      const stages = ['fixture-distiller', 'fixture-executor', 'fixture-executor', 'fixture-executor', 'fixture-responder'];
      const model = scriptedAI((request, index) => {
        calls++;
        assert.equal(request.model, stages[index]);
        if (index === 1) executorSystem = request.chatPrompt.flatMap(message => message.role === 'system' ? [message.content] : []).join('\n');
        const response = responses[index]; assert.ok(response, 'unexpected extra stage request'); return response;
      }, { structuredOutputs: true });
      try {
        const result = await worker.forward(model, { task: 'Compute the invoice sum.' }, options(ctx));
        assert.equal(result.answer, '13');
        assert.equal(calls, responses.length);
        const bindings = worker.getState()?.runtimeBindings;
        assert.deepEqual(bindings?.amounts, [9, 4]);
        const total = bindings?.sum;
        assert.ok(typeof total === 'number');
        assert.equal(total, 13);
        results.push({ level, systemChars: executorSystem.length, total });
      } finally { worker.stop(); }
    }
    return { results, selection: 'both declared settings retain the invoice amounts and computed total; replay policy separately controls old-action visibility, not worker variable lifetime', proof: 'explicit stage routes, typed responder output and actual retained runtime arithmetic under scripted code; no prompt equality or comparative model accuracy claim' };
  },
},

